import sys
import requests
import json
import time
import os
import tempfile

if len(sys.argv) < 2:
    sys.stderr.write("错误: 缺少操作类型参数 (get_domain 或 get_records)\n")
    sys.exit(1)

operation = sys.argv[1]
base_url = "http://dnslog.cn"

# 使用临时文件存储Cookie
cookie_file = os.path.join(tempfile.gettempdir(), "dnslog_cookie.txt")

# 创建session以保持Cookie
session = requests.Session()

# 如果Cookie文件存在，加载Cookie
try:
    if os.path.exists(cookie_file):
        with open(cookie_file, 'r') as f:
            for line in f:
                if 'PHPSESSID' in line:
                    session.cookies.set('PHPSESSID', line.strip().split('=')[1])
except:
    pass

try:
    if operation == "get_domain":
        # 获取临时域名（这会设置Cookie）
        response = session.get(f"{base_url}/getdomain.php", timeout=10)
        response.raise_for_status()
        domain = response.text.strip().rstrip('%')

        # 保存Cookie到文件
        try:
            with open(cookie_file, 'w') as f:
                for cookie in session.cookies:
                    f.write(f"{cookie.name}={cookie.value}\n")
        except:
            pass

        if domain:
            result = {
                "status": "success",
                "domain": domain,
                "message": f"成功获取临时域名: {domain}",
                "usage": f"使用此域名进行DNS查询测试，例如: nslookup {domain} 或 ping http://{domain}",
                "note": "域名有效期为24小时，请及时查询记录"
            }
            print(json.dumps(result, ensure_ascii=False, indent=2))
        else:
            print(json.dumps({
                "status": "error",
                "message": "未能获取到域名，请稍后重试"
            }, ensure_ascii=False, indent=2))
            sys.exit(1)

    elif operation == "get_records":
        # 获取DNS查询记录
        if len(sys.argv) < 3:
            sys.stderr.write("错误: get_records 操作需要提供域名参数\n")
            sys.exit(1)

        domain = sys.argv[2]
        wait_time = int(sys.argv[3]) if len(sys.argv) > 3 and sys.argv[3] else 0

        # 如果指定了等待时间，先等待
        if wait_time > 0:
            print(f"等待 {wait_time} 秒后查询记录...", file=sys.stderr)
            time.sleep(wait_time)

        # 加载Cookie（如果存在）
        try:
            if os.path.exists(cookie_file):
                with open(cookie_file, 'r') as f:
                    for line in f:
                        if 'PHPSESSID' in line:
                            session.cookies.set('PHPSESSID', line.strip().split('=')[1])
        except:
            pass

        response = session.get(f"{base_url}/getrecords.php", params={"t": domain}, timeout=10)
        response.raise_for_status()
        records_text = response.text.strip().rstrip('%')

        if records_text and records_text != "[]" and records_text.strip():
            # 尝试解析为JSON（如果返回的是JSON格式）
            try:
                records = json.loads(records_text)
                if isinstance(records, list) and len(records) > 0:
                    result = {
                        "status": "success",
                        "domain": domain,
                        "record_count": len(records),
                        "records": records,
                        "message": f"发现 {len(records)} 条DNS查询记录"
                    }
                    print(json.dumps(result, ensure_ascii=False, indent=2))
                else:
                    result = {
                        "status": "no_records",
                        "domain": domain,
                        "records": [],
                        "message": "暂无DNS查询记录，目标可能尚未触发DNS查询"
                    }
                    print(json.dumps(result, ensure_ascii=False, indent=2))
            except json.JSONDecodeError:
                # 如果不是JSON，按行分割
                records = [line.strip() for line in records_text.split("\n") if line.strip() and line.strip() != "[]"]
                if records:
                    result = {
                        "status": "success",
                        "domain": domain,
                        "record_count": len(records),
                        "records": records,
                        "message": f"发现 {len(records)} 条DNS查询记录"
                    }
                    print(json.dumps(result, ensure_ascii=False, indent=2))
                else:
                    result = {
                        "status": "no_records",
                        "domain": domain,
                        "records": [],
                        "message": "暂无DNS查询记录"
                    }
                    print(json.dumps(result, ensure_ascii=False, indent=2))
        else:
            result = {
                "status": "no_records",
                "domain": domain,
                "records": [],
                "message": "暂无DNS查询记录，目标可能尚未触发DNS查询"
            }
            print(json.dumps(result, ensure_ascii=False, indent=2))

    else:
        sys.stderr.write(f"错误: 未知的操作类型 '{operation}'，支持的操作: get_domain, get_records\n")
        sys.exit(1)

except requests.RequestException as e:
    error_result = {
        "status": "error",
        "message": f"请求失败: {str(e)}",
        "suggestion": "请检查网络连接或稍后重试"
    }
    print(json.dumps(error_result, ensure_ascii=False, indent=2))
    sys.exit(1)
except Exception as e:
    error_result = {
        "status": "error",
        "message": f"执行出错: {str(e)}"
    }
    print(json.dumps(error_result, ensure_ascii=False, indent=2))
    sys.exit(1)

import sys
import json
import base64
import requests
import os

# ==================== FOFA配置 ====================
# 请在此处配置您的 FOFA API Key
# 您也可以在环境变量中设置：FOFA_API_KEY
# enable 默认为 false，需开启才能调用该MCP
FOFA_API_KEY = ""  # 请填写您的FOFA API密钥
# ==================================================

# FOFA API基础URL
base_url = "https://fofa.info/api/v1/search/all"

# 解析参数（从JSON字符串或命令行参数）
def parse_args():
    # 尝试从第一个参数读取JSON配置
    if len(sys.argv) > 1:
        try:
            # 确保 sys.argv[1] 是字符串
            arg1 = str(sys.argv[1])
            # 尝试解析为JSON
            config = json.loads(arg1)
            # 确保返回的是字典类型
            if isinstance(config, dict):
                return config
        except (json.JSONDecodeError, TypeError, ValueError):
            # 如果不是JSON，使用传统的位置参数方式
            pass

    # 传统位置参数方式（向后兼容）
    # 注意：api_key 不作为调用参数传入，而是从配置或环境变量读取
    # 参数位置：query=2, size=3, page=4, fields=5, full=6
    # 但在 sys.argv 中，由于 python3 -c "code" 的格式，实际位置需要调整
    # sys.argv[0] 是 '-c'，sys.argv[1] 开始是实际参数
    config = {}
    if len(sys.argv) > 1:
        config['query'] = str(sys.argv[1])
    if len(sys.argv) > 2:
        try:
            config['size'] = int(sys.argv[2])
        except (ValueError, TypeError):
            pass
    if len(sys.argv) > 3:
        try:
            config['page'] = int(sys.argv[3])
        except (ValueError, TypeError):
            pass
    if len(sys.argv) > 4:
        config['fields'] = str(sys.argv[4])
    if len(sys.argv) > 5:
        val = sys.argv[5]
        if isinstance(val, str):
            config['full'] = val.lower() in ('true', '1', 'yes')
        else:
            config['full'] = bool(val)
    return config

try:
    config = parse_args()

    # 确保 config 是字典类型
    if not isinstance(config, dict):
        error_result = {
            "status": "error",
            "message": f"参数解析错误: 期望字典类型，但得到 {type(config).__name__}",
            "type": "TypeError"
        }
        print(json.dumps(error_result, ensure_ascii=False, indent=2))
        sys.exit(1)

    # 从配置或环境变量获取 api_key
    api_key = os.getenv('FOFA_API_KEY', FOFA_API_KEY).strip()
    query = config.get('query', '').strip()

    if not api_key:
        error_result = {
            "status": "error",
            "message": "缺少FOFA配置: api_key（FOFA API密钥）",
            "required_config": ["api_key"],
            "note": "请在YAML文件的FOFA_API_KEY配置项中填写您的API密钥，或在环境变量FOFA_API_KEY中设置。API密钥可在FOFA个人中心获取: https://fofa.info/userInfo"
        }
        print(json.dumps(error_result, ensure_ascii=False, indent=2))
        sys.exit(1)

    if not query:
        error_result = {
            "status": "error",
            "message": "缺少必需参数: query（搜索查询语句）",
            "required_params": ["query"],
            "examples": [
                'app="Apache"',
                'title="登录"',
                'domain="example.com"',
                'ip="1.1.1.1"',
                'port="80"',
                'country="CN"',
                'city="Beijing"'
            ]
        }
        print(json.dumps(error_result, ensure_ascii=False, indent=2))
        sys.exit(1)

    # 构建请求参数
    params = {
        'key': api_key,
        'qbase64': base64.b64encode(query.encode('utf-8')).decode('utf-8')
    }

    # 可选参数
    if 'size' in config and config['size'] is not None:
        try:
            size = int(config['size'])
            if size > 0:
                params['size'] = size
        except (ValueError, TypeError):
            pass

    if 'page' in config and config['page'] is not None:
        try:
            page = int(config['page'])
            if page > 0:
                params['page'] = page
        except (ValueError, TypeError):
            pass

    if 'fields' in config and config['fields']:
        params['fields'] = str(config['fields']).strip()

    if 'full' in config and config['full'] is not None:
        full_val = config['full']
        if isinstance(full_val, bool):
            params['full'] = 'true' if full_val else 'false'
        elif isinstance(full_val, str):
            params['full'] = 'true' if full_val.lower() in ('true', '1', 'yes') else 'false'
        elif isinstance(full_val, (int, float)):
            params['full'] = 'true' if full_val != 0 else 'false'

    # 发送请求
    try:
        response = requests.get(base_url, params=params, timeout=30)
        response.raise_for_status()

        result_data = response.json()

        # 检查FOFA API返回的错误
        if result_data.get('error'):
            error_result = {
                "status": "error",
                "message": f"FOFA API错误: {result_data.get('errmsg', '未知错误')}",
                "error_code": result_data.get('error'),
                "suggestion": "请检查API密钥是否正确，或查询语句是否符合FOFA语法"
            }
            print(json.dumps(error_result, ensure_ascii=False, indent=2))
            sys.exit(1)

        # 格式化输出结果
        output = {
            "status": "success",
            "query": query,
            "size": result_data.get('size', 0),
            "page": result_data.get('page', 1),
            "total": result_data.get('total', 0),
            "results_count": len(result_data.get('results', [])),
            "results": result_data.get('results', []),
            "message": f"成功获取 {len(result_data.get('results', []))} 条结果"
        }

        print(json.dumps(output, ensure_ascii=False, indent=2))

    except requests.exceptions.RequestException as e:
        error_result = {
            "status": "error",
            "message": f"请求失败: {str(e)}",
            "suggestion": "请检查网络连接或FOFA API服务状态"
        }
        print(json.dumps(error_result, ensure_ascii=False, indent=2))
        sys.exit(1)

except Exception as e:
    error_result = {
        "status": "error",
        "message": f"执行出错: {str(e)}",
        "type": type(e).__name__
    }
    print(json.dumps(error_result, ensure_ascii=False, indent=2))
    sys.exit(1)

